window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]=window.__LIBQ["the-gioi-hoan-my"]["q11"]||{};window.__LIBQ["the-gioi-hoan-my"]["q11"]["factions"]={"updatedAt":"2026-07-26","count":41,"factions":[{"id":"dai-bang-toc","name":"Đại Bằng tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Đại bàng cánh vàng của Đại Bằng tộc"],"blurb":"Bộ tộc của các sinh linh Đại Bằng. Một trưởng bối cánh vàng tới lối ra Tiên cổ để đón hậu nhân.","detail":"Khi các thiên tài rời Tiên cổ, đại bàng cánh vàng của tộc công khai gọi hậu nhân trở về bên mình.","thanhVien":[{"ten":"Đại bàng cánh vàng của Đại Bằng tộc","chucVu":"Trưởng bối","tuChuong":"@c1004","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1004","nguon":["@c1004"]},{"id":"bo-toc-thiet-huyet-than-thu","name":"Bộ tộc Thiết Huyết thần thụ","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Không rõ","nhanVatChinh":["Cây già của bộ tộc Thiết Huyết thần thụ"],"blurb":"Bộ tộc sinh linh dạng thần thụ. Một cây già của tộc xuất hiện tại lối ra Tiên cổ để triệu tập hậu nhân.","detail":"Giữa lúc các Giáo chủ dò xét những thiên tài trở về, cây già của bộ tộc gọi toàn bộ hậu nhân tập hợp bên mình.","thanhVien":[{"ten":"Cây già của bộ tộc Thiết Huyết thần thụ","chucVu":"Trưởng bối","tuChuong":"@c1004","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1004","nguon":["@c1004"]},{"id":"chi-ton-dao-trang","name":"Chí Tôn đạo tràng","cn":"","type":"dao-trang","typeLabel":"Đạo tràng","diaBan":"Không rõ","nhanVatChinh":["Tề Đạo Lâm","Thạch Hạo"],"blurb":"Chí Tôn đạo tràng do Tề Đạo Lâm làm đạo chủ, còn Thạch Hạo là truyền nhân được ông công khai bảo vệ.","detail":"Khi Thạch Hạo bị nhiều Giáo chủ vây giết, Tề Đạo Lâm mang thi thể hậu bối các giáo tới cứu viện và tuyên bố sẽ trả thù bằng cách nhắm vào tinh anh hậu đại của những thế lực sát hại đệ tử mình.","lanhDaoHienThoi":"Tề Đạo Lâm","thanhVien":[{"ten":"Tề Đạo Lâm","chucVu":"Đạo chủ","tuChuong":"@c1005","trangThai":"đang hoạt động"},{"ten":"Thạch Hạo","chucVu":"Đệ tử truyền nhân","tuChuong":"@c1005","trangThai":"đang hoạt động"}],"trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1005","loai":"khai chiến","importance":"normal","giaiDoan":"Đạo chủ trở lại cứu viện","text":"Tề Đạo Lâm công khai bảo vệ Thạch Hạo và tuyên bố trả thù các thế lực dám giết đệ tử mình.","anchor":"Tên khốn bất tử nào giết đệ tử ta thì sẽ bị ta dùng gậy ông đập lưng ông","trangThaiMoc":"Đối đầu các đạo thống vây giết Thạch Hạo"}]},"capNhatToi":"@c1005","nguon":["@c1005"]},{"id":"bo-toc-yem","name":"Bộ tộc Yêm","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"Không rõ","nhanVatChinh":["Tuyết Lâm","Lão tổ bộ tộc Yêm"],"blurb":"Bộ tộc của Tuyết Lâm, có một lão tổ mang Hoàng huyết thuộc nhóm cao thủ cực mạnh đương thời.","detail":"Tuyết Lâm cầu xin lão tổ của tộc giúp người từng cứu mình.","caoThuManhNhat":"Lão tổ bộ tộc Yêm","thanhVien":[{"ten":"Tuyết Lâm","chucVu":"Tộc nhân","tuChuong":"@c1007","trangThai":"đang hoạt động"},{"ten":"Lão tổ bộ tộc Yêm","chucVu":"Lão tổ","tuChuong":"@c1007","trangThai":"đang hoạt động"}],"trangThai":"Đang tồn tại","capNhatToi":"@c1007","nguon":["@c1007"]},{"id":"toi-huyet-nhat-mach","name":"Tội huyết nhất mạch","cn":"","type":"truyen-thua","typeLabel":"Nhất mạch","diaBan":"Không rõ","nhanVatChinh":[],"blurb":"Tội huyết nhất mạch có mối thù không thể hóa giải với Hỏa Vân động, Kiếm cốc và Yêu Long đạo môn.","detail":"Ba môn phái Hỏa Vân động, Kiếm cốc và Yêu Long đạo môn đều được xác nhận là đối địch với nhất mạch này.","quanHe":"Đối địch với Hỏa Vân động, Kiếm cốc và Yêu Long đạo môn","trangThai":"Đang tồn tại","capNhatToi":"@c1007","nguon":["@c1007"]},{"id":"cac-giao-lien-thu","name":"Các giáo liên thủ","cn":"","type":"lien-minh","typeLabel":"Liên minh tình thế","diaBan":"Chiến trường bị đại trận phong tỏa","nhanVatChinh":["Chủ nhân Thiên quốc","Cốc chủ Kiếm cốc","Môn chủ Yêu Long đạo môn","Chủ nhân Ma Quỳ viên","Chủ nhân Thái Dương thần cung","Bá chủ Minh thổ","Cường giả La Phù chân cốc"],"blurb":"Liên minh tình thế gồm nhiều thế lực và bá chủ cấp Giáo chủ cùng vây giết Côn Bằng tử.","detail":"Các thành viên hợp lực phong tỏa bầu trời, triển khai nhiều pháp bảo và thần thông, đồng thời tuyên bố việc giết Côn Bằng tử là ý chí chung của chư giáo.","nguonGoc":"Được hình thành từ nhiều giáo phái cùng chung mục tiêu trấn áp và giết Côn Bằng tử.","tonChi":"Liên thủ vây giết Côn Bằng tử.","quyMo":"Nhiều thế lực cấp Giáo chủ.","quanHe":"Đối địch Côn Bằng tử và các viện quân Bằng tộc.","trangThai":"đang giao chiến","thanhVien":[{"ten":"Chủ nhân Thiên quốc","chucVu":"Người mở màn công kích","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Cốc chủ Kiếm cốc","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Môn chủ Yêu Long đạo môn","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Chủ nhân Ma Quỳ viên","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Chủ nhân Thái Dương thần cung","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Bá chủ Minh thổ","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"},{"ten":"Cường giả La Phù chân cốc","chucVu":"Thành viên liên quân","tuChuong":"@c1008","trangThai":"đang tham chiến"}],"capNhatToi":"@c1008","tabs":{"tienTrinh":[{"chuong":"@c1008","loai":"khai chiến","importance":"normal","giaiDoan":"Vây giết Côn Bằng tử","text":"Nhiều Giáo chủ liên thủ phong tỏa chiến trường và đồng loạt phát động cuộc vây giết Côn Bằng tử.","anchor":"đây chính là các giáo đang liên thủ giết chết","trangThaiMoc":"đang giao chiến"}]},"nguon":["@c1008"]},{"id":"di-dan-tien-co","name":"Di dân Tiên cổ","cn":"","type":"lien-minh","typeLabel":"Liên minh các tộc bản địa","diaBan":"Di địa Tiên cổ","nhanVatChinh":["Chín Giáo chủ di dân Tiên cổ","Ngân Huyết ma thụ"],"blurb":"Liên minh các tộc bản địa sinh sống trong di địa Tiên cổ, có chín Giáo chủ cùng tới chiến trường trợ giúp sinh linh Bất Diệt.","detail":"Các bá chủ của Bát Tí Hồn tộc, Mỹ Nhân tộc và những tộc bản địa khác bảo vệ đoạn cành cổ tổ Tế Linh. Chín Giáo chủ của họ đứng về phía sinh linh Bất Diệt và tạo thành lực lượng đối trọng với các Giáo chủ thượng giới.","quyMo":"Chín Giáo chủ tham gia đối đầu tại chiến trường.","caoThuManhNhat":"Chín Giáo chủ di dân Tiên cổ","soCaoThu":"Chín Giáo chủ","thanhVien":[{"ten":"Chín Giáo chủ di dân Tiên cổ","chucVu":"Bá chủ các tộc bản địa","tuChuong":"@c1009","trangThai":"đang hoạt động"},{"ten":"Ngân Huyết ma thụ","chucVu":"Bá chủ dân bản địa Tiên cổ","tuChuong":"@c1009","trangThai":"đang hoạt động"}],"trangThai":"Đang đối đầu các Giáo chủ thượng giới","tabs":{"tienTrinh":[{"chuong":"@c1009","loai":"liên minh","importance":"normal","giaiDoan":"Chín bá chủ tới trợ trận","text":"Chín Giáo chủ của các tộc bản địa Tiên cổ tới chiến trường và đứng về phía sinh linh Bất Diệt.","anchor":"Chín vị bá chủ trong di địa Tiên cổ cũng đã tới.","trangThaiMoc":"Tham gia đối đầu các Giáo chủ thượng giới"}]},"capNhatToi":"@c1009","nguon":["@c1009"]},{"id":"dang-xa-toc","name":"Đằng Xà tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Ba ngàn châu","nhanVatChinh":["Giáo chủ Đằng Xà tộc"],"blurb":"Đằng Xà tộc có một Giáo chủ tham gia liên quân vây công Liễu Thần.","detail":"Trong trận chiến, một Giáo chủ của tộc bị điện đồng do Liễu Thần quăng đi đập nát và chết tại chỗ.","thanhVien":[{"ten":"Giáo chủ Đằng Xà tộc","chucVu":"Giáo chủ","tuChuong":"@c1010","trangThai":"tu-vong"}],"trangThai":"Tồn tại","capNhatToi":"@c1010","tabs":{"tienTrinh":[{"chuong":"@c1010","loai":"khai chiến","importance":"normal","giaiDoan":"Tham chiến chống Liễu Thần","text":"Một Giáo chủ Đằng Xà tộc tham gia liên quân rồi bị điện đồng do Liễu Thần khống chế đập chết.","anchor":"một Giáo chủ của Đằng Xà tộc bị đập nát"}]},"nguon":["@c1010"]},{"id":"bo-toc-cua-thu-mat-vang","name":"Bộ tộc của thú mắt vàng","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"","nhanVatChinh":["Thú mắt vàng"],"blurb":"Bộ tộc do Thú mắt vàng giữ vị trí tộc trưởng. Bộ tộc mất người đứng đầu khi Thú mắt vàng bị điện đồng nghiền nổ thân thể tại chiến trường.","detail":"Thú mắt vàng từng kêu gọi quần hùng ngăn cản Liễu Thần, nhưng bị điện đồng giam cầm hư không rồi nghiền nổ thân thể ngay tại chiến trường. Sau trận chiến này, bộ tộc mất tộc trưởng. @c1011","lanhDaoHienThoi":"Khuyết vị sau khi Thú mắt vàng tử trận","trangThai":"Mất tộc trưởng","capNhatToi":"@c1011","thanhVien":[{"ten":"Thú mắt vàng","chucVu":"Tộc trưởng","tuChuong":"@c1011","trangThai":"tu-vong"}],"lanhDaoMoc":[{"ten":"Thú mắt vàng","tuChuong":"@c1011","denChuong":"@c1011"}],"tabs":{"tienTrinh":[{"chuong":"@c1011","loai":"đổi lãnh đạo","importance":"major","giaiDoan":"Tộc trưởng tử trận","text":"Bộ tộc mất tộc trưởng khi Thú mắt vàng bị điện đồng nghiền nổ thân thể tại chiến trường.","trangThaiMoc":"Mất tộc trưởng","anchor":"thú mắt vàng thân là tộc trưởng của một bộ tộc"}]},"nguon":["@c1011"],"dacDiem":"Do Thú mắt vàng giữ vị trí tộc trưởng trước khi người này tử trận tại chiến trường."},{"id":"thien-hat-toc","name":"Thiên Hạt tộc","cn":"","type":"bo-toc","typeLabel":"Bộ tộc","diaBan":"","nhanVatChinh":["Giáo chủ Thiên Hạt"],"blurb":"Thiên Hạt tộc là bộ tộc do Giáo chủ Thiên Hạt đứng đầu, từng thuộc phe vây công Liễu Thần. Tại chiến trường, vị giáo chủ hóa bản thể để né tránh và chống đỡ điện đồng nhưng cuối cùng bị nghiền nát thành mưa máu, khiến tộc mất đi người lãnh đạo. @c1011","detail":"Thiên Hạt tộc được biết đến thông qua Giáo chủ Thiên Hạt, người đứng đầu bộ tộc và là một thành viên trong phe vây công Liễu Thần. Trong trận chiến, Giáo chủ Thiên Hạt hóa thành bản thể, vận dụng tốc độ cực hạn để né tránh, đồng thời dùng đuôi chống lại điện đồng; tuy nhiên, cả đuôi lẫn thân thể đều bị phá hủy, bản thân bị nghiền nát thành mưa máu. Sau thất bại này, Thiên Hạt tộc mất Giáo chủ. @c1011","lanhDaoHienThoi":"Khuyết vị sau khi Giáo chủ Thiên Hạt tử trận","trangThai":"Mất Giáo chủ","capNhatToi":"@c1011","thanhVien":[{"ten":"Giáo chủ Thiên Hạt","chucVu":"Giáo chủ","tuChuong":"@c1011","trangThai":"tu-vong"}],"lanhDaoMoc":[{"ten":"Giáo chủ Thiên Hạt","tuChuong":"@c1011","denChuong":"@c1011"}],"tabs":{"tienTrinh":[{"chuong":"@c1011","loai":"đổi lãnh đạo","importance":"major","giaiDoan":"Giáo chủ tử trận","text":"Thiên Hạt tộc mất Giáo chủ khi người đứng đầu bị điện đồng nghiền nát thành mưa máu.","trangThaiMoc":"Mất Giáo chủ","anchor":"Giáo chủ Thiên hạt chết thảm, hình thể đều nát bấy"}]},"nguon":["@c1011"],"dacDiem":"Bộ tộc do Giáo chủ Thiên Hạt đứng đầu; người đứng đầu có bản thể mang đuôi và từng thuộc phe vây công Liễu Thần.","congNang":["Giáo chủ Thiên Hạt có thể hóa thành bản thể. @c1011","Giáo chủ Thiên Hạt có thể vận dụng tốc độ cực hạn để né tránh công kích. @c1011","Giáo chủ Thiên Hạt có thể dùng đuôi chống đỡ điện đồng. @c1011"]},{"id":"chin-dai-giao-chu-tien-co","name":"Chín đại Giáo chủ Tiên cổ","cn":"","type":"lien-minh","typeLabel":"Liên minh chiến đấu","diaBan":"Chiến trường hỗn chiến thượng giới","nhanVatChinh":["Chín Giáo chủ di dân Tiên cổ"],"blurb":"Liên minh gồm chín Giáo chủ Tiên cổ cùng bảo vệ Thạch Hạo và ngăn các cường giả đối địch.","detail":"Chín Giáo chủ liên thủ nghênh địch, tuyên bố những kẻ muốn giết Hoang phải vượt qua họ. Sau khi nhận ra Liễu Thần là cổ tổ Tế Linh, họ tiếp tục cùng nó liều chết chinh chiến.","nguonGoc":"Các Giáo chủ của di dân Tiên cổ liên thủ trong cuộc hỗn chiến","tonChi":"Bảo vệ Hoang và cùng cổ tổ Tế Linh chiến đấu","quyMo":"Chín Giáo chủ","caoThuManhNhat":"Chín Giáo chủ di dân Tiên cổ","soCaoThu":"Chín Giáo chủ","trangThai":"Đang liên thủ chiến đấu","thanhVien":[{"ten":"Chín Giáo chủ di dân Tiên cổ","chucVu":"Thành viên liên minh","tuChuong":"@c1012","trangThai":"Đang tham chiến"}],"tabs":{"tienTrinh":[{"chuong":"@c1012","loai":"liên minh","importance":"normal","giaiDoan":"Liên thủ bảo vệ Hoang","trangThaiMoc":"Đang chiến đấu","text":"Chín Giáo chủ Tiên cổ liên thủ ngăn những người xông tới giết Thạch Hạo và tiếp tục chiến đấu sau khi nhận ra Liễu Thần là cổ tổ Tế Linh.","anchor":"Chín đại Giáo chủ cùng nhau liên thủ đối địch, ngăn cản những người xông lại."}]},"capNhatToi":"@c1012","nguon":["@c1012"]},{"id":"tuyet-hoang-toc","name":"Tuyết Hoàng tộc","cn":"","type":"gia-toc","typeLabel":"Tộc quần","diaBan":"Ba ngàn châu","nhanVatChinh":["Lão tộc trưởng Tuyết Hoàng tộc"],"blurb":"Tộc quần do một lão tộc trưởng đại diện tại chiến trường nơi Liễu Thần chấm dứt đại chiến.","detail":"Lão tộc trưởng Tuyết Hoàng tộc tới cùng các Giáo chủ khác sau khi Liễu Thần đã định đoạt cục diện và chuẩn bị kết thúc chiến sự.","lanhDaoHienThoi":"Lão tộc trưởng Tuyết Hoàng tộc","thanhVien":[{"ten":"Lão tộc trưởng Tuyết Hoàng tộc","chucVu":"Lão tộc trưởng","tuChuong":"@c1014","trangThai":"Đang tại vị"}],"trangThai":"Đang tồn tại","capNhatToi":"@c1014","nguon":["@c1014"]},{"id":"cac-dao-thong-ba-ngan-chau","name":"Các đạo thống ba ngàn châu","cn":"","type":"quan-the","typeLabel":"Quần thể đạo thống","diaBan":"Ba ngàn châu","nhanVatChinh":[],"blurb":"Tên gọi chung cho các đạo thống hoạt động tại ba ngàn châu.","detail":"Liễu Thần công khai cảnh cáo toàn bộ quần thể này rằng bất kỳ đạo thống nào lấy lớn hiếp nhỏ, trấn áp hoặc mưu hại Thạch Hạo đều bị xem là tuyên chiến và có thể bị tiêu diệt.","quanHe":"Bị Liễu Thần răn đe không được mưu hại Thạch Hạo.","trangThai":"Bị cảnh cáo công khai","capNhatToi":"@c1014","tabs":{"tienTrinh":[{"chuong":"@c1014","loai":"khai chiến","importance":"normal","giaiDoan":"Bị chiếu cáo và răn đe","text":"Liễu Thần tuyên bố sẽ tiêu diệt bất kỳ đạo thống nào tại ba ngàn châu lấy lớn hiếp nhỏ hoặc mưu hại Thạch Hạo.","anchor":"bất kể là đạo thống nào, nếu lấy lớn hiếp hỏ, ta chắc chắn sẽ tới thăm hỏi và diệt sạch đạo thống của kẻ đó"}]},"nguon":["@c1014"]},{"id":"lien-minh-cuu-thien-thap-dia","name":"Liên minh Cửu Thiên Thập Địa","cn":"","type":"lien-minh","typeLabel":"Liên minh","diaBan":"Cửu Thiên Thập Địa","nhanVatChinh":[],"blurb":"Liên minh Cửu Thiên Thập Địa là sự liên kết đang được chuẩn bị thành lập giữa các lực lượng thuộc Cửu Thiên Thập Địa. Cùng với liên minh, ba viện dành cho những kỳ tài mạnh nhất cũng được dự kiến thiết lập.","detail":"Liên minh có quy mô bao trùm Cửu Thiên Thập Địa, hình thành từ sự liên kết giữa các lực lượng trong phạm vi này. Trong quá trình chuẩn bị thành lập, liên minh đồng thời dự kiến xây dựng Thánh viện, Tiên viện và Thư viện Thiên Thần để tuyển chọn, bồi dưỡng những kỳ tài mạnh nhất. @c1017","nguonGoc":"Sự liên kết giữa các lực lượng thuộc Cửu Thiên Thập Địa","tonChi":"Tuyển chọn và bồi dưỡng những người mạnh nhất","quyMo":"Cửu Thiên Thập Địa","tranPhai":["Thánh viện","Tiên viện","Thư viện Thiên Thần"],"trangThai":"Đang chuẩn bị thành lập","capNhatToi":"@c1017","tabs":{"tienTrinh":[{"chuong":"@c1017","loai":"lập","importance":"major","giaiDoan":"Chuẩn bị thành lập","text":"Liên minh Cửu Thiên Thập Địa được chuẩn bị thành lập cùng ba viện dành cho những kỳ tài mạnh nhất.","anchor":"liên minh của cửu Thiên thập Địa chuẩn bị thành lập, sẽ thành lập nên Thánh viện, Tiên viện, thư viện Thiên Thần","trangThaiMoc":"Đang chuẩn bị thành lập"}]},"nguon":["@c1017"],"dacDiem":"Liên minh quy mô Cửu Thiên Thập Địa, gắn với ba viện dành cho những kỳ tài mạnh nhất.","congNang":["Liên kết các lực lượng thuộc Cửu Thiên Thập Địa. @c1017","Thành lập Thánh viện, Tiên viện và Thư viện Thiên Thần nhằm tuyển chọn, bồi dưỡng những kỳ tài mạnh nhất. @c1017"]},{"id":"khach-toi-tu-vuc-ngoai","name":"Khách tới từ vực ngoại","cn":"","type":"nhom-tu-si","typeLabel":"Nhóm tu sĩ","diaBan":"Ba ngàn châu","nhanVatChinh":["Lâm Thiên"],"blurb":"Nhóm Thiên Thần trẻ tuổi từ vực ngoại liên tiếp đánh bại các kỳ tài trở về từ Tiên cổ và công khai khiêu chiến Trích tiên, Hoang.","detail":"Nhóm khách vực ngoại gồm vài Thiên Thần trẻ tuổi có hoa đại đạo do tiên khí hóa thành. Họ quét ngang những người cùng thế hệ tại ba ngàn châu, chê bai truyền thừa bản địa đã sa sút và cho rằng các thiên tài nơi đây khó có tư cách tiến vào Thư viện Thiên Thần.","quyMo":"Vài Thiên Thần trẻ tuổi","thanhVien":[{"ten":"Lâm Thiên","chucVu":"Thành viên","tuChuong":"@c1020","trangThai":"đang hoạt động"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1020","tabs":{"tienTrinh":[{"chuong":"@c1020","loai":"khai chiến","importance":"normal","giaiDoan":"Khiêu chiến thiên tài ba ngàn châu","text":"Nhóm khách vực ngoại đánh bại các kỳ tài trở về từ Tiên cổ rồi công khai gọi Trích tiên và Hoang ra giao chiến.","anchor":"bọn họ quét ngang thượng giới, những người cùng thế hệ không ai địch nổi","trangThaiMoc":"Đang thách đấu các kỳ tài ba ngàn châu"}]},"nguon":["@c1020"]},{"id":"tien-phu","name":"Tiên phủ","cn":"","type":"dao-phu","typeLabel":"Đạo phủ","diaBan":"Thế giới sau Tử Trúc lâm","nhanVatChinh":["Cô gái do Tiên Hoàng hóa thành"],"blurb":"Đạo phủ mênh mông trong thế giới sau Tử Trúc lâm, nơi nhiều tuấn kiệt trẻ tuổi của các tộc tụ hội.","detail":"Tiên phủ tổ chức một thịnh hội dành cho những người trẻ kiệt xuất của nhiều tộc. Cư dân tại đây dường như không biết tới ba ngàn đạo châu.","quyMo":"Mênh mông vô tận theo lời cư dân, quy tụ nhiều tuấn kiệt của các tộc.","thanhVien":[{"ten":"Cô gái do Tiên Hoàng hóa thành","chucVu":"Cư dân tham dự thịnh hội","tuChuong":"@c1037","trangThai":"Đang hoạt động"}],"trangThai":"Đang tổ chức thịnh hội","capNhatToi":"@c1037","tabs":{"tienTrinh":[{"chuong":"@c1037","loai":"nhắc tới","importance":"normal","giaiDoan":"Thịnh hội tuấn kiệt","text":"Tiên phủ tổ chức cuộc tụ hội dành cho những người trẻ kiệt xuất của nhiều tộc.","anchor":"Rất nhiều tuấn kiệt trẻ tuổi tới tụ hội, họ đều là những người kiệt xuất nhất của các tộc"}]},"nguon":["@c1037"]},{"id":"doi-muoi-chin","name":"Đội Mười Chín","cn":"","aliases":["Toán Thiên Thần phục kích"],"type":"khac","typeLabel":"Toán chiến đấu","diaBan":"Nơi sâu Cấm khu","nhanVatChinh":["Thủ lĩnh toán Thiên Thần","Thiên Thần bị bắt"],"blurb":"Đội Mười Chín là một toán Thiên Thần thiện chiến cưỡi hung thú, từng phục kích Thạch Hạo tại nơi sâu trong Cấm khu. Sau khi thủ lĩnh tử trận, toàn đội cùng một số tọa kỵ bị Thạch Hạo truy sát và giết sạch @c1042.","detail":"Các thành viên Đội Mười Chín hợp lực vây đánh Thạch Hạo và từng định dùng đá nhiều màu bố trí trận pháp. Khi thủ lĩnh tử trận, họ tìm cách tháo chạy; một số thành viên rơi vào trạng thái mắt đỏ như máu, chiến đấu điên cuồng. Cuối cùng, toàn bộ toán Thiên Thần phục kích cùng một số tọa kỵ đều bị Thạch Hạo truy sát và tiêu diệt @c1042.","quyMo":"Một toán Thiên Thần cùng nhiều tọa kỵ","caoThuManhNhat":"Thủ lĩnh toán Thiên Thần","trangThai":"bị tiêu diệt","thanhVien":[{"ten":"Thủ lĩnh toán Thiên Thần","chucVu":"Thủ lĩnh","tuChuong":"@c1042","trangThai":"tử vong"},{"ten":"Thiên Thần bị bắt","chucVu":"Thành viên","tuChuong":"@c1042","trangThai":"tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1042","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Bị Thạch Hạo tiêu diệt","trangThaiMoc":"Bị tiêu diệt","text":"Toàn bộ toán Thiên Thần phục kích cùng một số tọa kỵ bị Thạch Hạo truy sát và giết sạch.","anchor":"Kết quả, không một ai có thể chạy thoát, toàn bộ bị giết sạch"}]},"capNhatToi":"@c1042","nguon":["@c1042"],"uyLuc":"Từng hợp lực vây đánh Thạch Hạo tại nơi sâu trong Cấm khu, nhưng sau đó toàn đội cùng một số tọa kỵ bị truy sát và giết sạch @c1042.","dacDiem":"Một toán Thiên Thần thiện chiến cưỡi hung thú; một số thành viên có biểu hiện mắt đỏ như máu khi chiến đấu điên cuồng.","congNang":["Cưỡi hung thú phối hợp phục kích và vây đánh mục tiêu.","Có thể dùng đá nhiều màu để bố trí trận pháp.","Một số thành viên có thể rơi vào trạng thái mắt đỏ như máu và chiến đấu điên cuồng."]},{"id":"cac-doi-thien-than-ma-hoa-trong-cam-khu","name":"Các đội Thiên Thần ma hóa trong Cấm khu","cn":"","type":"luc-luong","typeLabel":"Lực lượng ma hóa","diaBan":"Cấm khu","nhanVatChinh":["Đội trưởng đội Thiên Thần ma hóa","Đội Thiên Thần ma hóa"],"blurb":"Lực lượng gồm những tu sĩ vốn thuộc ba ngàn châu nhưng đã bị ảnh hưởng từ Biên hoang làm tâm thần sa đọa.","detail":"Các thành viên được tổ chức thành từng đội Thiên Thần, mang mắt đỏ và truy sát những người tiến sâu vào Cấm khu. Họ có thể dùng huyết tế để gọi sinh linh từ bên kia Biên hoang.","nguonGoc":"Các tu sĩ vốn thuộc ba ngàn châu nhưng bị ma hóa","quyMo":"Gồm nhiều đội Thiên Thần hoạt động trong Cấm khu","thanhVien":[{"ten":"Đội trưởng đội Thiên Thần ma hóa","chucVu":"Đội trưởng","tuChuong":"@c1044","trangThai":"Đang hoạt động"},{"ten":"Đội Thiên Thần ma hóa","chucVu":"Đội truy sát","tuChuong":"@c1044","trangThai":"Đang hoạt động"}],"trangThai":"Đang hoạt động","tabs":{"tienTrinh":[{"chuong":"@c1044","loai":"khai chiến","importance":"normal","giaiDoan":"Truy sát và triệu gọi","text":"Một đội Thiên Thần ma hóa truy sát Thạch Hạo rồi dùng huyết tế để gọi sinh linh bên kia Biên hoang.","anchor":"Những người này vốn thuộc về ba ngàn châu, chỉ là bị ma hóa","trangThaiMoc":"Ảnh hưởng từ Biên hoang đã xâm nhập sâu vào Cấm khu"}]},"capNhatToi":"@c1044","nguon":["@c1044"]},{"id":"tu-si-cuu-thien","name":"Tu sĩ Cửu Thiên","cn":"","type":"nhom-tu-si","typeLabel":"Nhóm tu sĩ","diaBan":"Khu phố chợ ngoài Đế thành","nhanVatChinh":["Chàng trai tóc vàng","Người bình phẩm Ma nữ"],"blurb":"Nhóm tu sĩ đến từ Cửu Thiên tụ tập thành một phe riêng tại khu phố chợ ngoài Đế thành.","detail":"Nhóm này không thuộc ba ngàn châu và thể hiện sự tự tin vào thiên tài Cửu Thiên. Một thành viên tóc vàng đánh giá Thạch Hạo và Ma nữ bất phàm nhưng vẫn kém người của Cửu Thiên.","nguonGoc":"Cửu Thiên","thanhVien":[{"ten":"Chàng trai tóc vàng","chucVu":"Tu sĩ trẻ","tuChuong":"@c1049","trangThai":"Đang hiện diện"},{"ten":"Người bình phẩm Ma nữ","chucVu":"Thành viên","tuChuong":"@c1049","trangThai":"Đang hiện diện"}],"trangThai":"Tụ tập ngoài Đế thành","capNhatToi":"@c1049","tabs":{"tienTrinh":[{"chuong":"@c1049","loai":"nhắc tới","importance":"normal","giaiDoan":"Chạm mặt tu sĩ ba ngàn châu","text":"Một nhóm tu sĩ không thuộc ba ngàn châu xuất hiện riêng biệt tại khu phố chợ và đánh giá thiên tài Cửu Thiên cao hơn những người mới tới.","anchor":"Trừ hắn ra còn có một vài người khác tựa như không thuộc về ba ngàn châu này","trangThaiMoc":"Tụ tập ngoài Đế thành"}]},"nguon":["@c1049"]},{"id":"thien-than-thu-vien","name":"Thiên Thần thư viện","cn":"","aliases":["Thư viện Thiên Thần"],"type":"hoc-vien","typeLabel":"Thư viện tu luyện","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Vị chí tôn trung niên chủ trì tuyển chọn","Tam đại Chí Cường giả","Mười lăm thiên tài Thiên Thần Thư Viện","Hai trưởng lão Thiên Thần Thư Viện","Nhóm học sinh Thiên Thần Thư Viện trấn giữ sơn môn","Lục Đà"],"blurb":"Thiên Thần Thư Viện là thế lực dự kiến xây dựng tại Vô Lượng Thiên, từng tổ chức tuyển chọn thiên tài ở biên hoang mà không ấn định hạn ngạch cho ba ngàn đạo châu. Thư viện khảo nghiệm người dự tuyển qua nhiệm vụ thanh trừ kẻ sa vào bóng tối, đồng thời duy trì quy củ báo danh nghiêm ngặt và để các đệ tử nòng cốt công khai tuyển chọn người theo đuổi. (+) Thế lực tu hành tập hợp nhiều thiên kiêu và đệ tử. Thư viện mở chuyến tiến vào tiên gia chiến trường theo nguyên tắc tự nguyện rồi dùng hoàng kim cự thuyền đưa người tham gia lên đường. [CAN-SOAT-GOP] (+) Thế lực cử nhiều trưởng lão và đệ tử tới tìm kiếm cơ duyên tại Âm Dương nhãn. Sau khi thăm dò thung lũng, họ đồng ý tạm thời hợp tác với Tiên Viện để mở Càn Khôn lô. [CAN-SOAT-GOP]","detail":"Thiên Thần Thư Viện được cho là đang dự kiến xây dựng tại Vô Lượng Thiên, thu hút những thiên tài vừa thoát khỏi biến cố. Trong đợt tuyển chọn tại biên hoang, người dự tuyển được lập đội tối đa năm thành viên, tiến vào các cổ thành để tìm và thanh trừ những kẻ bị khí tức không tên ăn mòn, qua đó kiểm tra thần giác cùng khả năng hợp tác. Thư viện treo phần thưởng đặc biệt và cam kết dốc toàn lực bồi dưỡng người mang được Bạch Kỳ Lân ấu thú trở về. Thế lực này không tiếp nhận những thiên tài bỏ lỡ thời hạn báo danh dù họ nhiều lần tìm đến; về sau, các đệ tử nòng cốt còn xuất hiện để công khai tuyển chọn người theo đuổi. Hai trưởng lão của thư viện từng cảm nhận được chấn động từ cổ khoáng và lo ngại những bí mật bên trong tái hiện.","tonChi":"Tuyển chọn và bồi dưỡng thiên tài đủ năng lực đối diện nguy cơ tại biên hoang.","lanhDaoHienThoi":"Không rõ","capBac":"Thế lực đào tạo thiên tài","trangThai":"Đang hoạt động","capNhatToi":"@c1051","thanhVien":[{"ten":"Vị chí tôn trung niên chủ trì tuyển chọn","chucVu":"Người chủ trì tuyển chọn","tuChuong":"@c1051","trangThai":"đang hoạt động"},{"ten":"Tam đại Chí Cường giả","chucVu":"Người phụ trách tuyển chọn","tuChuong":"@c1051","trangThai":"đang hoạt động"},{"ten":"Mười lăm thiên tài Thiên Thần Thư Viện","chucVu":"Thiên tài học viên","tuChuong":"@c1081","trangThai":"bi-bat-giu"},{"ten":"Hai trưởng lão Thiên Thần Thư Viện","chucVu":"Trưởng lão","tuChuong":"@c1081","trangThai":"dang-hoat-dong"},{"ten":"Nhóm học sinh Thiên Thần Thư Viện trấn giữ sơn môn","chucVu":"Học sinh trấn giữ sơn môn","tuChuong":"@c1091","trangThai":"Đang hoạt động"},{"ten":"Lục Đà","chucVu":"Đệ tử","tuChuong":"@c1092","trangThai":"Đang thuộc thư viện"},{"ten":"Thạch Hạo","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"đang tham chiến"},{"ten":"Vương Hi","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"đang tham chiến"},{"ten":"Lục Đà","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"đang tham chiến"},{"ten":"Phong Hành Thiên","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"Tham gia chuyến đi"},{"ten":"Yêu Nguyệt","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"đang tham chiến"},{"ten":"Huyền Côn","chucVu":"Đệ tử","tuChuong":"@c1102","trangThai":"đang tham chiến"},{"ten":"Nguyên Phong","chucVu":"Đệ tử chính thức","tuChuong":"@c1102","trangThai":"Tham gia chuyến đi"},{"ten":"Trưởng lão có tổ tiên bị mượn hài cốt","chucVu":"Trưởng lão","tuChuong":"@c1119","trangThai":"Đang thuộc thư viện"},{"ten":"Nhị trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1202","trangThai":"Đang hoạt động"},{"ten":"Ngũ Trưởng Lão","chucVu":"Trưởng lão","tuChuong":"@c1202","trangThai":"Đang hoạt động"},{"ten":"Tam Trưởng Lão","chucVu":"Trưởng lão","tuChuong":"@c1202","trangThai":"Đang hoạt động"},{"ten":"Tứ trưởng lão","chucVu":"Trưởng lão","tuChuong":"@c1202","trangThai":"Đang hoạt động"},{"ten":"Thạch Hạo","chucVu":"Đệ tử","tuChuong":"@c1202","trangThai":"Đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1051","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Thử thách tuyển sinh tại biên hoang","text":"Thiên Thần thư viện mở thử thách thanh trừ người sa vào bóng tối và treo phần thưởng đặc biệt cho người mang Bạch Kỳ Lân trở về.","anchor":"ai nếu như có thể mang về, Thiên Thần thư viện đem dốc hết toàn bộ tâm huyết bồi dưỡng người kia","trangThaiMoc":"Đang tuyển sinh"},{"chuong":"@c1067","loai":"lập","importance":"normal","giaiDoan":"Dự kiến kiến lập","text":"Thiên Thần Thư Viện được cho là đang dự kiến xây dựng tại Vô Lượng Thiên, thu hút những thiên tài vừa thoát vây.","anchor":"mấy năm trước thì, nghe người ta nói khả năng muốn ở Vô Lượng Thiên kiến một toà","trangThaiMoc":"Đang dự kiến kiến lập"},{"chuong":"@c1081","loai":"nhắc tới","importance":"normal","giaiDoan":"Theo dõi dị động cổ khoáng","text":"Hai trưởng lão Thiên Thần Thư Viện cảm nhận chấn động từ cổ khoáng và lo ngại những bí mật bên trong tái hiện.","anchor":"Chính là Thiên Thần Thư Viện hai tên trưởng lão cũng đều trên mặt biến sắc"},{"chuong":"@c1091","loai":"nhắc tới","importance":"normal","giaiDoan":"Giữ nguyên quyết định hủy tư cách","text":"Thiên Thần Thư Viện tiếp tục không thu nhận những thiên tài đã bỏ lỡ thời hạn báo danh, dù họ thường xuyên trở lại khiêu chiến.","anchor":"Làm sao, Thiên Thần Thư Viện vì giết gà dọa khỉ, vẫn không thu hắn nhập môn.","trangThaiMoc":"Từ chối người báo danh quá hạn"},{"chuong":"@c1092","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Mở sơn môn tuyển người","text":"Các đệ tử nòng cốt của Thiên Thần Thư Viện xuất hiện và công khai tuyển chọn người theo đuổi.","anchor":"Đệ tử nòng cốt các loại (chờ) đều đi ra, muốn chọn rút người theo đuổi rồi!","trangThaiMoc":"Mở sơn môn tuyển người theo đuổi"}]},"nguon":["@c1051","@c1067","@c1081","@c1091","@c1092","@c1102","@c1119","@c1134","@c1149","@c1202"],"dacDiem":"Tuyển chọn không theo hạn ngạch cố định nhưng giữ nghiêm thời hạn báo danh; chú trọng thần giác, khả năng hợp tác và cho phép lập đội tối đa năm người.","congNang":["Tổ chức tuyển chọn thiên tài tại biên hoang mà không đặt hạn ngạch cố định cho ba ngàn đạo châu. @c1051","Dùng nhiệm vụ tìm và thanh trừ những kẻ bị khí tức không tên ăn mòn trong các cổ thành để kiểm tra thần giác và khả năng hợp tác của người dự tuyển. @c1051","Cho phép người dự tuyển lập đội với tối đa năm thành viên. @c1051","Treo phần thưởng đặc biệt và cam kết dốc toàn lực bồi dưỡng người mang được Bạch Kỳ Lân ấu thú trở về. @c1051","Thu hút thiên tài đến Vô Lượng Thiên. @c1067","Các trưởng lão có thể cảm nhận chấn động phát ra từ cổ khoáng. @c1081","Thi hành nghiêm thời hạn báo danh, không thu nhận người đã bỏ lỡ thời hạn. @c1091","Các đệ tử nòng cốt công khai tuyển chọn người theo đuổi. @c1092"]},{"id":"gia-toc-hoang-kim","name":"Gia tộc hoàng kim","cn":"","type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Chàng trai tóc vàng"],"blurb":"Gia tộc tại Vô Lượng Thiên có tổ tiên do Hoàng Đạo Tiên Kim thông linh hóa thành người. Hậu duệ kế thừa khả năng kim loại hóa huyết nhục.","detail":"Gia tộc hoàng kim muốn đưa Bạch Kỳ Lân về cho cổ tổ vì huyết của nó được cho là có tác dụng khó lường. Chàng trai tóc vàng là một hậu duệ có thể thi triển bí pháp huyết mạch để hóa thân thể thành hoàng kim.","nguonGoc":"Tổ tiên là Hoàng Đạo Tiên Kim thông linh hóa thành hình người.","thanhVien":[{"ten":"Chàng trai tóc vàng","chucVu":"Hậu duệ","tuChuong":"@c1054","trangThai":"Đang thuộc gia tộc"}],"quanHe":"Tranh đoạt Bạch Kỳ Lân để phục vụ cổ tổ trong tộc.","trangThai":"Đang tồn tại","tabs":{"tienTrinh":[{"chuong":"@c1054","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ nguồn gốc huyết mạch","text":"Nguồn gốc của gia tộc hoàng kim được hé lộ là bắt đầu từ Hoàng Đạo Tiên Kim thông linh hóa thành người.","trangThaiMoc":"Đang tồn tại","anchor":"bọn họ tổ tiên là Hoàng Đạo Tiên Kim thông linh mà thành, hóa thành hình người"}]},"capNhatToi":"@c1054","nguon":["@c1054"]},{"id":"thien-tien-thu-vien","name":"Thiên Tiên thư viện","cn":"","type":"thu-vien","typeLabel":"Thư viện tu luyện","diaBan":"Gần Thần Nhai thư viện","nhanVatChinh":["Phượng Vũ"],"blurb":"Thư viện tu luyện có Phượng Vũ là truyền nhân kiệt xuất nhất. Nơi này nằm gần Thần Nhai thư viện.","detail":"Thiên Tiên thư viện đào tạo những truyền nhân trẻ tuổi, trong đó Phượng Vũ được đánh giá là truyền nhân kiệt xuất nhất và là một sơ đại mạnh mẽ.","quyMo":"Có truyền nhân sơ đại mạnh mẽ","thanhVien":[{"ten":"Phượng Vũ","chucVu":"Truyền nhân kiệt xuất nhất","tuChuong":"@c1055","trangThai":"Đang thuộc"}],"capNhatToi":"@c1055","nguon":["@c1055"]},{"id":"than-nhai-thu-vien","name":"Thần Nhai thư viện","cn":"","type":"thu-vien","typeLabel":"Thư viện tu luyện","diaBan":"Hỏa Châu","nhanVatChinh":["Tả Tiểu Địch","Mục Tử Tiêu"],"blurb":"Thư viện tu luyện tọa lạc tại Hỏa Châu và nằm gần Thiên Tiên thư viện. Tả Tiểu Địch cùng Mục Tử Tiêu đều xuất thân từ đây.","detail":"Thần Nhai thư viện là thế lực tại Hỏa Châu, có quan hệ địa lý gần với Thiên Tiên thư viện và đào tạo những ứng cử viên như Tả Tiểu Địch, Mục Tử Tiêu.","thanhVien":[{"ten":"Tả Tiểu Địch","chucVu":"Truyền nhân","tuChuong":"@c1055","trangThai":"Đang thuộc"},{"ten":"Mục Tử Tiêu","chucVu":"Truyền nhân","tuChuong":"@c1055","trangThai":"Đang thuộc"}],"capNhatToi":"@c1055","nguon":["@c1055"]},{"id":"cu-dan-cac-co-thanh-ben-kia-bien-hoang","name":"Cư dân các cổ thành bên kia biên hoang","cn":"","aliases":[],"type":"lien-minh-chung-toc","typeLabel":"Cộng đồng nhiều chủng tộc","diaBan":"Hơn mười cổ thành trên bình nguyên bên kia biên hoang","nhanVatChinh":["Lão nhân trong thành Nhân tộc","Cư dân thành Nhân tộc","Hai Nhân tộc bình thường ngoài thành"],"blurb":"Cộng đồng gồm bảy, tám chủng tộc sinh sống trong hơn mười cổ thành ở thế giới bên kia biên hoang. Khoảng một nửa số thành trì thuộc Nhân tộc, các thành tương đối hòa thuận và cùng sử dụng một loại cổ ngữ.","detail":"Các cổ thành đều có cao thủ mạnh mẽ tọa trấn. Cư dân Nhân tộc tại đây tuyên bố Cửu Thiên Thập Địa vốn là linh thổ của họ bị đối phương chiếm đoạt và muốn đánh sang để thu hồi.","nguonGoc":"Chưa rõ","quyMo":"Hơn mười cổ thành thuộc bảy, tám chủng tộc","quanHe":"Các thành trì tương đối hòa thuận và cùng sử dụng một loại cổ ngữ.","trangThai":"Đang tồn tại","thanhVien":[{"ten":"Lão nhân trong thành Nhân tộc","chucVu":"Cư dân","tuChuong":"@c1059","trangThai":"Đang sinh sống"},{"ten":"Cư dân thành Nhân tộc","chucVu":"Cư dân","tuChuong":"@c1059","trangThai":"Đang sinh sống"},{"ten":"Hai Nhân tộc bình thường ngoài thành","chucVu":"Cư dân bình thường","tuChuong":"@c1059","trangThai":"Đang sinh sống"}],"capNhatToi":"@c1059","tabs":{"tienTrinh":[{"chuong":"@c1059","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Thạch Hạo khảo sát","text":"Thạch Hạo phát hiện hơn mười cổ thành do bảy, tám chủng tộc nắm giữ, trong đó khoảng một nửa thuộc Nhân tộc.","anchor":"tất cả đều có cao thủ mạnh mẽ tọa trấn, cộng bảy, tám cái chủng tộc","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1059"]},{"id":"cac-dai-co-giao-ben-kia-bien-hoang","name":"Các đại cổ giáo bên kia Biên Hoang","cn":"","aliases":[],"type":"co-giao","typeLabel":"Các cổ giáo","diaBan":"Thế giới bên kia Biên Hoang","nhanVatChinh":[],"blurb":"Những cổ giáo lớn tại thế giới bên kia Biên Hoang. Họ đồng loạt động viên cho một cuộc đại chiến với mục tiêu được công bố là trở về cửu thiên thập địa.","detail":"Các đại cổ giáo bắt đầu chuẩn bị cho cuộc chiến được mô tả là chưa từng có. Tin tức lưu truyền cho rằng nếu chiến dịch thành công, sinh linh của thế giới này có thể vượt Biên Hoang và trở lại cửu thiên thập địa.","trangThai":"Đang động viên chuẩn bị đại chiến","capNhatToi":"@c1060","tabs":{"tienTrinh":[{"chuong":"@c1060","loai":"khai chiến","importance":"normal","giaiDoan":"Động viên trước đại chiến","text":"Các đại cổ giáo đồng loạt động viên cho một cuộc đại chiến chưa từng có, với hy vọng trở về cửu thiên thập địa nếu thành công.","anchor":"Tất cả đại cổ giáo tại động viên, có lẽ phải có đại chiến mở ra.","trangThaiMoc":"Đang chuẩn bị chiến tranh"}]},"nguon":["@c1060"]},{"id":"cac-dai-thanh-dia-di-gioi","name":"Các đại thánh địa dị giới","cn":"","type":"thanh-dia","typeLabel":"Các thánh địa","diaBan":"Dị giới","nhanVatChinh":[],"blurb":"Những thánh địa lớn tại dị giới đồng loạt chấn động khi thần niệm và pháp chỉ của Bất Hủ giả giáng tới. Cao thủ các phương đến Bất Hủ sơn yết kiến rồi chuẩn bị cho cuộc chiến với Cửu Thiên.","detail":"Các đại thánh địa dị giới quy tụ nhiều cao thủ và nhân vật thủ lĩnh. Sau khi tiếp nhận tin tiên chiến sắp mở, họ thể hiện thái độ coi thường Cửu Thiên Thập Địa, tuyên bố sẽ giết trở về và đoạt lại những gì cho là thuộc về mình.","quanHe":"Chuẩn bị đối địch với Cửu Thiên Thập Địa","trangThai":"Đang chuẩn bị tiên chiến","capNhatToi":"@c1063","tabs":{"tienTrinh":[{"chuong":"@c1063","loai":"khai chiến","importance":"normal","giaiDoan":"Chuẩn bị chiến tranh","text":"Các đại thánh địa dị giới đến Bất Hủ sơn yết kiến sau khi pháp chỉ giáng xuống và bắt đầu chuẩn bị chiến tranh với Cửu Thiên.","anchor":"các Đại Thánh địa không ai không chấn động, chư hơn cao thủ đồng thời làm lễ Bất Hủ sơn","trangThaiMoc":"Đang chuẩn bị tiên chiến"}]},"nguon":["@c1063"]},{"id":"de-thanh-the-luc","name":"Đế Thành","cn":"","type":"thanh-tri","typeLabel":"Thành trì","diaBan":"Đế Thành","nhanVatChinh":["Người có giọng già nua ra lệnh trở về thành"],"blurb":"Thế lực nội bộ Đế Thành, nơi xảy ra xung đột khi Gia Đức cưỡng ép Thạch Hạo. Từng có oan khuất lớn liên quan đến Lôi Đế chiến y hắc ám hóa.","detail":"Nội bộ Đế Thành phát sinh xung đột khi Gia Đức cưỡng ép sưu hồn Thạch Hạo, dẫn đến giao chiến với người can thiệp bảo vệ. Một nhân vật cấp cao phải quát dừng để tránh tự tàn sát phe mình. Nơi đây từng xảy ra oan khuất lớn khiến Lôi Đế chiến y hắc ám hóa và lưu lạc bên ngoài.","nguonGoc":"Chưa rõ","trangThai":"Đang hoạt động, nội bộ có xung đột","thanhVien":[{"ten":"Gia Đức","chucVu":"Người kiểm tra (đến từ Vô Lượng Thiên)","tuChuong":"@c1064","trangThai":"hoat-dong"},{"ten":"Người can thiệp bảo vệ Thạch Hạo","chucVu":"Thành viên","tuChuong":"@c1064","trangThai":"hoat-dong"},{"ten":"Người có giọng già nua ra lệnh trở về thành","chucVu":"Nhân vật cấp cao","tuChuong":"@c1064","trangThai":"hoat-dong"},{"ten":"Thạch Hạo","chucVu":"Thiên tài được đưa vào hạch tâm","tuChuong":"@c1064","trangThai":"hoat-dong"}],"tabs":{"tienTrinh":[{"chuong":"@c1064","loai":"khai chiến","importance":"normal","giaiDoan":"Xung đột nội bộ","trangThaiMoc":"Nội bộ bất ổn","text":"Gia Đức cưỡng ép sưu hồn Thạch Hạo, một người khác can thiệp giao chiến với hắn. Nhân vật cấp cao quát dừng cuộc nội chiến, ra lệnh trở về thành.","anchor":"Hai người các ngươi ra tay như thế, còn thể thống gì, không biết xấu hổ cùng xấu hổ sao, người mình đi đầu tàn sát lên!"}]},"capNhatToi":"@c1064","nguon":["@c1064"]},{"id":"luc-luong-tran-thu-de-thanh-cua-cuu-thien-thap-dia","name":"Lực lượng trấn thủ Đế Thành của Cửu Thiên Thập Địa","cn":"","aliases":[],"type":"lien-minh","typeLabel":"Thế lực liên hợp","diaBan":"Đế Thành","nhanVatChinh":["Ông lão tóc bạc cầm nanh sói đại bổng","Gia Đức","Những người trấn thủ cổ xưa trong Đế Thành"],"blurb":"Lực lượng liên hợp do nhiều cổ giới thuộc Cửu Thiên Thập Địa cử tới trấn giữ Đế Thành. Thành viên thuộc nhiều chủng tộc, sử dụng cổ ngữ khác nhau và phân tán tại các khu vực trong nội thành.","detail":"Những người trấn thủ cư trú trong khu vực cốt lõi của Đế Thành, nơi liên quan tới Thái cổ Minh Ước. Một số người đã ngồi bất động suốt thời gian rất dài, trong khi những người khác vẫn can thiệp khi xảy ra biến cố và cùng xử lý các nguy cơ hắc ám.","nguonGoc":"Nhân mã do các cổ giới thuộc Cửu Thiên Thập Địa phái tới.","tonChi":"Trấn giữ Đế Thành và chống lại đại địch.","quyMo":"Gồm nhân mã từ nhiều cổ giới và nhiều chủng tộc.","thanhVien":[{"ten":"Ông lão tóc bạc cầm nanh sói đại bổng","chucVu":"Người trấn thủ","tuChuong":"@c1065","trangThai":"Đang hoạt động"},{"ten":"Gia Đức","chucVu":"Người trấn thủ","tuChuong":"@c1065","trangThai":"Bị buộc bế quan"},{"ten":"Những người trấn thủ cổ xưa trong Đế Thành","chucVu":"Tu sĩ trấn thủ","tuChuong":"@c1065","trangThai":"Đang trấn thủ"}],"trangThai":"Đang trấn thủ Đế Thành","tabs":{"tienTrinh":[{"chuong":"@c1065","loai":"nhắc tới","importance":"normal","giaiDoan":"Nhiều cổ giới cùng thủ thành","text":"Thạch Hạo nhận ra nhiều cổ giới thuộc Cửu Thiên Thập Địa đều phái nhân mã tới đóng giữ Đế Thành.","anchor":"Cửu Thiên Thập Địa, cái khác cổ giới đều phái có nhân mã đóng tại này","trangThaiMoc":"Đang trấn thủ"}]},"capNhatToi":"@c1065","nguon":["@c1065"]},{"id":"the-luc-xich-huyet-hao","name":"Thế lực Xích Huyết hào","cn":"","aliases":[],"type":"hai-tac","typeLabel":"Thế lực hải tặc","diaBan":"Tinh không Vô Lượng Thiên và khu vực Thái Sơ tinh","nhanVatChinh":["Chủ nhân Xích Huyết hào"],"blurb":"Một thế lực hải tặc nổi danh tại Vô Lượng Thiên, chuyên vận chuyển nô lệ có tu vi tới Thái Sơ cổ quáng.","detail":"Thế lực này dùng Xích Huyết hào qua lại tinh không, bắt giữ hoặc mua bán nô lệ rồi đưa họ tới các khu khai thác thần liệu. Nhóm duy trì quan hệ lợi ích ngầm với nhiều thế lực lớn.","lanhDaoHienThoi":"Chủ nhân Xích Huyết hào","quyMo":"Có bảo thuyền dài hàng vạn trượng và vận chuyển đông đảo tù nhân.","quanHe":"Có giao dịch ngầm với nhiều thế lực lớn và cung cấp nô lệ cho các bên khai khoáng.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Chủ nhân Xích Huyết hào","chucVu":"Lãnh đạo","tuChuong":"@c1069","trangThai":"Đang tại vị"}],"lanhDaoMoc":[{"ten":"Chủ nhân Xích Huyết hào","tuChuong":"@c1069","denChuong":""}],"capNhatToi":"@c1069","tabs":{"tienTrinh":[{"chuong":"@c1069","loai":"nhắc tới","importance":"normal","giaiDoan":"Vận chuyển nô lệ khai khoáng","text":"Thế lực Xích Huyết hào đưa một đoàn nô lệ tới Thái Sơ tinh và duy trì giao dịch ngầm với nhiều thế lực lớn.","anchor":"nó cùng rất nhiều thế lực lớn trong bóng tối có lui tới"}]},"nguon":["@c1069"]},{"id":"co-the-gia-mua-thach-hao","name":"Cổ thế gia mua Thạch Hạo","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Cổ thế gia","diaBan":"Thái sơ ngôi sao","nhanVatChinh":["Tiểu thư Vương tộc mang tiên huyết","Ông lão dò xét ký ức","Ông lão chiêu dụ Thạch Hạo"],"blurb":"Một Cổ thế gia hoạt động khai khoáng tại Thái sơ ngôi sao, đã mua Thạch Hạo cùng vài nghìn người làm nô lệ.","detail":"Gia tộc dự định đặt cấm chế lên những người bị mua để ép họ khai thác thiên tài địa bảo đến chết. Sau khi kỳ thạch dò xét bị phá vỡ và Thạch Hạo phô bày hai đạo tiên khí, cao tầng phong tỏa hiện trường rồi cân nhắc đưa hắn tới Thiên Thần thư viện với điều kiện đi theo tiểu thư trong tộc.","quyMo":"Có khả năng mua và quản lý vài nghìn nô lệ khai khoáng","quanHe":"Có liên hệ với Thiên Thần Thư Viện thông qua tiểu thư trong tộc.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Tiểu thư Vương tộc mang tiên huyết","chucVu":"Tiểu thư","tuChuong":"@c1070","trangThai":"Đang ở Thiên Thần Thư Viện"},{"ten":"Ông lão dò xét ký ức","chucVu":"Cao thủ kiểm tra nô lệ","tuChuong":"@c1070","trangThai":"Đang hoạt động"},{"ten":"Ông lão chiêu dụ Thạch Hạo","chucVu":"Người đại diện chiêu dụ","tuChuong":"@c1070","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1070","tabs":{"tienTrinh":[{"chuong":"@c1070","loai":"nhắc tới","importance":"normal","giaiDoan":"Mua và kiểm tra Thạch Hạo","text":"Mua Thạch Hạo cùng vài nghìn người làm nô lệ khai khoáng, sau đó phong tỏa khu vực khi phát hiện tư chất khác thường của hắn.","anchor":"hắn cùng mấy ngàn người bị bán ột Cổ thế gia, đem vì bọn họ đào thiên tài địa bảo."}]},"nguon":["@c1070"]},{"id":"vuong-toc","name":"Vương tộc","cn":"","aliases":["Trường Sinh gia tộc họ Vương"],"type":"gia-toc","typeLabel":"Trường Sinh gia tộc","diaBan":"Khu vực do bộ tộc chiếm giữ trên Thái Sơ tinh","nhanVatChinh":["Tiểu thư Vương tộc mang tiên huyết","Các trưởng giả Vương tộc tại khu mỏ"],"blurb":"Trường Sinh gia tộc lấy Vương làm họ, lưu truyền từ thời Tiên cổ. Thủy tổ của họ từng là nhân vật Tiên đạo và được truyền rằng đã chạm tới lĩnh vực Tiên Vương trước khi chết trận.","detail":"Vương tộc kiểm soát một khu vực trên Thái Sơ tinh và cử người thăm dò Thái Sơ cổ quáng. Họ đề nghị giúp Thạch Hạo thoát thân phận nô lệ và tới Thiên Thần Thư Viện nếu hắn tìm được Sinh mệnh chi thạch cho tiểu thư mang tiên huyết.","nguonGoc":"Bộ tộc lưu truyền từ Tiên cổ, có thủy tổ từng là người trường sinh.","quyMo":"Trường Sinh gia tộc có lực lượng hoạt động tại khu mỏ trên Thái Sơ tinh.","caoThuManhNhat":"Thủy tổ được truyền rằng từng chạm tới lĩnh vực Tiên Vương","quanHe":"Giao dịch với Thạch Hạo và sắp xếp hắn làm chiến phó của tiểu thư trong tộc.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Tiểu thư Vương tộc mang tiên huyết","chucVu":"Tiểu thư mang tiên huyết","tuChuong":"@c1071","trangThai":"Đang thuộc Vương tộc"},{"ten":"Các trưởng giả Vương tộc tại khu mỏ","chucVu":"Trưởng giả phụ trách khu mỏ","tuChuong":"@c1071","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1071","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1071","loai":"nhắc tới","importance":"normal","giaiDoan":"Giao dịch với Thạch Hạo","text":"Vương tộc tiết lộ nguồn gốc Trường Sinh gia tộc và giao Thạch Hạo nhiệm vụ tìm Sinh mệnh chi thạch để đổi lấy tự do cùng cơ hội tới Thiên Thần Thư Viện.","anchor":"tục truyền là từ Tiên cổ sống sót bộ tộc","trangThaiMoc":"Đang hoạt động"}]},"nguon":["@c1071"]},{"id":"lien-minh-tham-do-cua-cac-the-gia-va-co-giao","name":"Liên minh thăm dò của các thế gia và cổ giáo","cn":"","type":"lien-minh","typeLabel":"Liên minh thăm dò","diaBan":"Thái Sơ ngôi sao","nhanVatChinh":["Nhóm tử sĩ của các thế gia và cổ giáo","Tử sĩ mặc hắc giáp vàng trụ"],"blurb":"Liên minh tạm thời của nhiều thế gia và cổ giáo nhằm thăm dò Thái Sơ cổ quáng. Mấy chục tử sĩ được phái tới cửa mỏ và lực lượng trực tiếp tiến vào gần như chết sạch.","detail":"Các thế gia và cổ giáo cùng tổ chức hành động thăm dò Thái Sơ cổ quáng, điều động những cao thủ đã được bồi dưỡng làm tử sĩ. Hơn hai mươi người chết bởi mưa sáng trước cửa mỏ, còn số nhảy xuống theo Thạch Hạo đều tử vong giữa đường.","tonChi":"Thăm dò Thái Sơ cổ quáng","thanhVien":[{"ten":"Nhóm tử sĩ của các thế gia và cổ giáo","chucVu":"Lực lượng thăm dò","tuChuong":"@c1072","trangThai":"Đã tử vong"},{"ten":"Tử sĩ mặc hắc giáp vàng trụ","chucVu":"Người xung phong","tuChuong":"@c1072","trangThai":"Đã tử vong"}],"trangThai":"Lực lượng trực tiếp thăm dò gần như bị diệt sạch","tabs":{"tienTrinh":[{"chuong":"@c1072","loai":"suy","importance":"normal","giaiDoan":"Thăm dò cổ quáng","text":"Liên minh phái mấy chục tử sĩ tới Thái Sơ cổ quáng, nhưng lực lượng trực tiếp tiến vào gần như chết sạch.","anchor":"Thăm dò Thái Sơ cổ quáng, các đại thế gia cùng cổ giáo liên hợp hành động đều muốn đi tới nơi đó.","trangThaiMoc":"Lực lượng thăm dò gần như bị diệt sạch"}]},"capNhatToi":"@c1072","nguon":["@c1072"]},{"id":"truong-sinh-gia-toc-cua-vuong-toc-tieu-thu","name":"Trường Sinh gia tộc của Vương tộc tiểu thư","cn":"","type":"gia-toc","typeLabel":"Trường Sinh gia tộc","diaBan":"Không rõ","nhanVatChinh":["Vương tộc tiểu thư"],"blurb":"Một Trường Sinh gia tộc có quý nữ mang huyết thống Nhân Tiên đang tu hành tại Thiên Thần Thư Viện.","detail":"Gia tộc này được nhắc tới thông qua Vương tộc tiểu thư, một hậu duệ Nhân Tiên có địa vị quý nữ và đang tu hành trong Thiên Thần Thư Viện.","thanhVien":[{"ten":"Vương tộc tiểu thư","chucVu":"Quý nữ","tuChuong":"@c1074","trangThai":"dang-thuoc"}],"capNhatToi":"@c1074","nguon":["@c1074"]},{"id":"vuong-gia","name":"Vương gia","cn":"","aliases":["Vương tộc","Trường Sinh thế gia Vương gia"],"type":"gia-toc","typeLabel":"Trường Sinh gia tộc","diaBan":"Thái Sơ tinh","nhanVatChinh":["Người Vương gia xác nhận tung tích Thạch Hạo","Vương Hi"],"blurb":"Vương gia là một Trường Sinh gia tộc có người hoạt động tại khu vực Thái Sơ cổ quáng. Gia tộc từng nhắm tới việc thu phục Thạch Hạo, dùng Kim Cương trác ép hắn phục vụ Vương Hi và sau đó xác nhận việc hắn đã xuống cổ khoáng nhưng chưa trở lại.","detail":"Người của Vương gia từng đánh giá Thạch Hạo, kẻ đã tu thành hai đạo tiên khí, có thể trở thành trợ lực mạnh nếu chịu nghe lệnh Vương Hi. Vì mục đích này, họ đeo Kim Cương trác lên người hắn để cưỡng ép hắn phục vụ Vương Hi. Sau khi Thạch Hạo mất tích, một thành viên Vương gia công khai xác nhận hắn đã tiến vào Thái Sơ cổ quáng và chưa trở về.","quyMo":"Trường Sinh gia tộc","thanhVien":[{"ten":"Người Vương gia xác nhận tung tích Thạch Hạo","chucVu":"Thành viên Vương gia","tuChuong":"@c1076","trangThai":"Đang hoạt động"},{"ten":"Vương Hi","chucVu":"Minh châu của tộc","tuChuong":"@c1092","trangThai":"Thành viên"},{"ten":"Vương Hi","chucVu":"Minh châu của gia tộc","tuChuong":"@c1149","trangThai":"bị cuốn vào lời đồn"},{"ten":"Những người trẻ tuổi Vương gia tại thư viện","chucVu":"Lớp trẻ của gia tộc","tuChuong":"@c1149","trangThai":"đang hoạt động"},{"ten":"Vương Mãng Long","chucVu":"Thành viên","tuChuong":"@c1293","trangThai":"tu-vong"},{"ten":"Ông lão Vương gia","chucVu":"Cường giả tiền bối","tuChuong":"@c1293","trangThai":"tu-vong"},{"ten":"Vương Trường Sinh","chucVu":"Người đứng đầu","tuChuong":"@c1299","trangThai":"Đang lãnh đạo"},{"ten":"Vương Đại","chucVu":"Con trưởng Vương Trường Sinh","tuChuong":"@c1299","trangThai":"Đang tham chiến"},{"ten":"Vương Nhị","chucVu":"Con thứ hai Vương Trường Sinh","tuChuong":"@c1299","trangThai":"Đang tham chiến"},{"ten":"Vương Cửu","chucVu":"Con thứ chín Vương Trường Sinh","tuChuong":"@c1299","trangThai":"Đang tham chiến"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1076","tabs":{"tienTrinh":[{"chuong":"@c1076","loai":"nhắc tới","importance":"normal","giaiDoan":"Công khai tung tích Thạch Hạo","text":"Một thành viên Vương gia xác nhận Thạch Hạo đã xuống Thái Sơ cổ quáng và chưa trở lại, đồng thời dựa vào địa vị Trường Sinh gia tộc để không e ngại lời chỉ trích.","anchor":"Người nhà họ Vương cũng không sợ, bởi vì bọn họ là Trường Sinh gia tộc, không cần lo lắng ai chỉ trích","trangThaiMoc":"Đang hoạt động tại khu vực Thái Sơ cổ quáng"},{"chuong":"@c1092","loai":"nhắc tới","importance":"normal","giaiDoan":"Mưu đồ thu phục Thạch Hạo","text":"Mục đích người Vương gia đeo Kim Cương trác lên Thạch Hạo được xác nhận là để ép hắn phục vụ Vương Hi.","anchor":"trên đầu hắn Kim Cương trác chính là tộc này người ở Thái Sơ cổ quáng cho hắn mang theo, chính là vì thu phục đến cho nữ tử này khi (làm) tôi tớ.","trangThaiMoc":"Đang tìm cách khống chế Thạch Hạo"}]},"nguon":["@c1076","@c1092","@c1149","@c1268","@c1293","@c1299"],"dacDiem":"Là Trường Sinh gia tộc, hành động nhằm thu phục nhân tài làm trợ lực cho Vương Hi.","congNang":["Dùng Kim Cương trác đeo lên Thạch Hạo nhằm cưỡng ép hắn phục vụ Vương Hi. @c1092","Nắm và công khai xác nhận tung tích của Thạch Hạo tại Thái Sơ cổ quáng. @c1076"]},{"id":"nguyet-te-toc","name":"Nguyệt Tê tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Nữ tu áo tím Nguyệt Tê tộc"],"blurb":"Một tộc tại Vô Lượng Thiên có nữ truyền nhân tiến vào Thái Sơ cổ quáng. Nữ truyền nhân này cùng bốn đồng bạn tranh đoạt tiên dược trì với Thạch Hạo.","detail":"Nguyệt Tê tộc được nhắc đến thông qua nữ truyền nhân thuộc nhóm năm người Vô Lượng Thiên. Trong cổ khoáng, nàng tham gia thúc giục Cửu Hoàng Lô để đối phó Thạch Hạo.","thanhVien":[{"ten":"Nữ tu áo tím Nguyệt Tê tộc","chucVu":"Truyền nhân","tuChuong":"@c1078","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1078","nguon":["@c1078"]},{"id":"vo-luong-thien-the-luc","name":"Vô Lượng Thiên","cn":"","aliases":[],"type":"khu-vuc-the-luc","typeLabel":"Thế lực khu vực","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Nữ tu áo tím Nguyệt Tê tộc","Lục Đà"],"blurb":"Thế lực tu hành tại Vô Lượng Thiên, có những kỳ tài đương đại và cổ đại vương giả đã tu ra tiên khí.","detail":"Năm cao thủ đến từ Vô Lượng Thiên giao chiến với Thạch Hạo trong cổ khoáng nhưng đều bị đánh bại và trấn áp.","quyMo":"Có khả năng bồi dưỡng nhiều kỳ tài tu ra tiên khí.","thanhVien":[{"ten":"Nữ tu áo tím Nguyệt Tê tộc","chucVu":"Kỳ tài","tuChuong":"@c1079","trangThai":"đang thuộc"},{"ten":"Lục Đà","chucVu":"Sư huynh","tuChuong":"@c1079","trangThai":"được nhắc đến"}],"tabs":{"tienTrinh":[{"chuong":"@c1079","loai":"nhắc tới","importance":"normal","giaiDoan":"Năm cao thủ thất bại","text":"Năm cao thủ Vô Lượng Thiên bị Thạch Hạo lần lượt đánh bại và trấn áp trong cổ khoáng.","anchor":"Đây chính là cái gọi là Vô Lượng Thiên cao thủ, chỉ đến như thế!","trangThaiMoc":"Năm cao thủ bị đánh bại"}]},"capNhatToi":"@c1079","nguon":["@c1079"]},{"id":"chi-ton-cung-dien","name":"Chí Tôn cung điện","cn":"","aliases":[],"type":"truyen-thua","typeLabel":"Truyền thừa","diaBan":"","nhanVatChinh":[],"blurb":"Truyền thừa sở hữu tuyệt học Lục Đạo Luân Hồi Thiên Công.","detail":"Kinh văn thuộc tuyệt học của Chí Tôn cung điện được phát hiện vang lên từ sâu trong Thái Sơn cổ quáng khi Cửu Hoàng lô gây cộng hưởng.","tranPhai":"Lục Đạo Luân Hồi Thiên Công","tabs":{"tienTrinh":[{"chuong":"@c1079","loai":"nhắc tới","importance":"normal","giaiDoan":"Tuyệt học hiện trong cổ khoáng","text":"Lục Đạo Luân Hồi Thiên Công của Chí Tôn cung điện được phát hiện dưới dạng tiếng tụng kinh trong Thái Sơn cổ quáng.","anchor":"Lục Đạo Luân Hồi đại pháp, thuộc về Chí Tôn cung điện tuyệt học","trangThaiMoc":"Tuyệt học được phát hiện trong cổ khoáng"},{"chuong":"@c1081","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ truyền thừa","text":"Chí Tôn cung điện được xác nhận là nguồn truyền thừa của Lục Đạo Luân Hồi Thiên Công và có liên hệ với Tiên cổ.","anchor":"Chí Tôn cung điện truyền thừa cực kỳ kỷ nguyên, cùng Tiên cổ có chút liên quan"}]},"capNhatToi":"@c1079","nguon":["@c1079","@c1081"]},{"id":"phong-toc","name":"Phong tộc","cn":"","type":"gia-toc","typeLabel":"Trường Sinh thế gia","diaBan":"Cửu Thiên Thập Địa","nhanVatChinh":["Phong Hành Thiên"],"blurb":"Một trong những Trường Sinh gia tộc đáng sợ nhất, có mâu thuẫn từ đời trước với một vị vương thuộc Thạch tộc tại Biên Hoang. (+) Trường Sinh thế gia bị lời đồn gần đây chỉ ra là thế lực đã thỉnh cầu Nguyên Thanh áp chế Thạch Hạo. [CAN-SOAT-GOP]","detail":"Thông tin về sự can dự của Phong tộc mới chỉ là tin tức ngầm và chưa được xác nhận. Phong Hành Thiên là kỳ tài của tộc, đã tu thành ba đạo tiên khí.","thanhVien":[{"ten":"Phong Hành Thiên","chucVu":"Kỳ tài","tuChuong":"@c1088","trangThai":"đang-thuộc"},{"ten":"Phong Hành Thiên","chucVu":"Thành viên","tuChuong":"@c1109","trangThai":"đang hoạt động"},{"ten":"Phong Chiêu","chucVu":"Phong Hầu","tuChuong":"@c1114","trangThai":"đang hoạt động"}],"trangThai":"hoạt động","capNhatToi":"@c1088","nguon":["@c1088","@c1109","@c1114","@c1178"],"tabs":{}},{"id":"truong-sinh-the-gia","name":"Trường Sinh thế gia","cn":"","type":"nhom-gia-toc","typeLabel":"Nhóm gia tộc","diaBan":"Cửu Thiên","nhanVatChinh":[],"blurb":"Danh xưng dành cho những gia tộc có tổ tiên từng thành tiên. Trải qua vô lượng năm tháng, các gia tộc này vẫn được quốc gia cổ, Thánh địa và nhiều chủng tộc hùng mạnh kính trọng.","detail":"Trường Sinh thế gia có nền tảng lâu đời và uy thế kinh người vì tổ tiên từng xuất hiện tiên. Người ngoài cho rằng họ có thể còn lưu giữ những thủ đoạn do Trường Sinh giả truyền lại.","nguonGoc":"Các gia tộc có tổ tiên từng thành tiên.","quyMo":"Có địa vị khiến quốc gia cổ, Thánh địa và các chủng tộc hùng mạnh phải lễ kính.","trangThai":"Đang tồn tại","capNhatToi":"@c1091","tabs":{"tienTrinh":[{"chuong":"@c1091","loai":"nhắc tới","importance":"bridge","giaiDoan":"Uy thế được bàn luận","text":"Đám đông ngoài sơn môn bàn luận về uy thế và truyền nhân của các Trường Sinh thế gia.","anchor":"Trường Sinh thế gia, đó là tổ tiên từng ra tiên gia tộc, chỉ riêng lấy thực lực đến luận, dù cho quá khứ vô lượng năm tháng, như trước khủng bố kinh thế.","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1091"]},{"id":"bach-ho-toc","name":"Bạch Hổ tộc","cn":"","type":"gia-toc","typeLabel":"Tộc quần","diaBan":"Không rõ","nhanVatChinh":["Bạch Hoành"],"blurb":"Tộc quần có huyết thống cao quý, với Bạch Hoành là một cường giả trẻ tuổi nổi danh của thế hệ này.","detail":"Bạch Hoành, thiên kiêu của Bạch Hổ tộc, từng gần được Thiên Thần Thư Viện tuyển chọn và sau đó tự nguyện hóa bản thể kéo xe cho Yêu Nguyệt.","thanhVien":[{"ten":"Bạch Hoành","chucVu":"Thiên kiêu trẻ tuổi","tuChuong":"@c1092","trangThai":"Thành viên"}],"tabs":{"tienTrinh":[{"chuong":"@c1092","loai":"nhắc tới","importance":"normal","giaiDoan":"Thiên kiêu hạ mình kéo xe","text":"Bạch Hoành, cường giả trẻ tuổi mang huyết thống cao quý của Bạch Hổ tộc, tự nguyện phục vụ Yêu Nguyệt.","anchor":"Bạch Hoành, một cái anh tư bộc phát thanh niên, bạch y nho nhã, huyết thống cao quý, là một cái vô cùng nổi danh tuổi trẻ cường giả","trangThaiMoc":"Bạch Hoành trở thành thần thú kéo xe cho Yêu Nguyệt"}]},"capNhatToi":"@c1092","nguon":["@c1092"]},{"id":"truong-sinh-hoang-trieu","name":"Trường Sinh Hoàng triều","cn":"","type":"hoang-trieu","typeLabel":"Hoàng triều","diaBan":"","nhanVatChinh":["Yêu Nguyệt"],"blurb":"Hoàng triều trường sinh nơi công chúa Yêu Nguyệt xuất thân.","detail":"Yêu Nguyệt, tuyệt thế tiên tử đã tu thành ba đạo tiên khí, được xác nhận là công chúa đến từ thế lực này.","thanhVien":[{"ten":"Yêu Nguyệt","chucVu":"Công chúa","tuChuong":"@c1100","trangThai":"đương nhiệm"}],"capNhatToi":"@c1100","nguon":["@c1100"]}]};
